-- Тема 08: варианты ответов выровнены по длине и форме (80 исправлений в 26 вопросах), ключи не меняются.
-- Источник: scripts/questions/081_option_length_topic08.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Какие базы данных создаются при инициализации кластера?', 'Только postgres', 'Одна база данных postgres', 'Создаются ещё два шаблона.', 'Кроме postgres создаются ещё два шаблона.'),
        ('option', 'Какие базы данных создаются при инициализации кластера?', 'Только template0 и template1', 'Два шаблона: template0 и template1', 'Создаётся ещё база postgres.', 'Кроме двух шаблонов создаётся ещё база postgres.'),
        ('option', 'Для чего нужен шаблон template0?', 'Для восстановления из pg_dump и для создания базы с другой кодировкой', 'Для восстановления pg_dump и другой кодировки', 'Чистый шаблон, в котором нет изменений template1.', 'Чистый шаблон, в котором нет изменений template1: из него создают базу для восстановления из pg_dump и базу с другой кодировкой.'),
        ('option', 'Для чего нужен шаблон template0?', 'Для хранения ролей кластера', 'Для хранения ролей и привилегий кластера', 'Роли общие для всего кластера и хранятся не в шаблоне.', NULL),
        ('option', 'Для чего нужен шаблон template0?', 'Для подключения по умолчанию', 'Для подключения клиентов по умолчанию', 'По умолчанию подключаются к базе с именем пользователя.', NULL),
        ('option', 'Для чего нужен шаблон template0?', 'Для хранения временных таблиц', 'Для хранения временных таблиц сеансов', 'Временные таблицы создаются в той базе, где работает сеанс.', NULL),
        ('option', 'Что такое схема в PostgreSQL?', 'Синоним пользователя', 'Синоним имени пользователя базы', 'Схема и пользователь — разные сущности.', NULL),
        ('option', 'Что такое схема в PostgreSQL?', 'Отдельный каталог на диске', 'Отдельный каталог на диске базы', 'Схема — логическое понятие, на диске отдельного каталога у неё нет.', NULL),
        ('option', 'Что такое схема в PostgreSQL?', 'Пространство имён для объектов внутри базы данных', 'Пространство имён для объектов внутри базы', 'Объекты с одинаковыми именами могут лежать в разных схемах.', NULL),
        ('option', 'Что такое схема в PostgreSQL?', 'Копия базы данных', 'Копия базы данных внутри одного кластера', 'Схема находится внутри базы данных.', NULL),
        ('option', 'С объектами каких баз может работать клиент в рамках одного подключения?', 'Баз из одного табличного пространства', 'Баз из одного табличного пространства кластера', 'Табличные пространства на доступ к базам не влияют.', NULL),
        ('option', 'С объектами каких баз может работать клиент в рамках одного подключения?', 'Только той базы, к которой подключён, но в любых её схемах', 'Той базы, к которой подключён, во всех схемах', 'Для другой базы нужно новое подключение.', NULL),
        ('option', 'С объектами каких баз может работать клиент в рамках одного подключения?', 'Любых, если это суперпользователь', 'Любых баз кластера, если это суперпользователь', 'Даже суперпользователь в одном подключении работает с одной базой.', NULL),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Перебираются схемы из search_path слева направо', 'Схемы из search_path слева направо', 'Используется первая одноимённая таблица в фактическом пути поиска, включая неявно добавленные схемы. Для перегруженных функций правило сложнее: учитываются и типы аргументов.', NULL),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Всегда используется public', 'Используется схема public по умолчанию', 'public используется, только если она есть в пути.', 'public используется, если она есть в пути поиска; сам путь определяет порядок.'),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Используется pg_catalog', 'Используется схема pg_catalog первой', 'Если pg_catalog нет в пути, она неявно просматривается перед ним; поиск идёт по всему пути.', NULL),
        ('option', 'В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', 'Всегда в public', 'В схему public, если она есть в пути поиска', 'Только если она первая подходящая в пути.', 'Public используется, если она первая подходящая в пути.'),
        ('option', 'В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', 'В последнюю схему пути поиска', 'В последнюю существующую схему пути поиска', 'Используется первая подходящая схема, а не последняя.', NULL),
        ('option', 'В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', 'В pg_temp', 'В схему pg_temp текущего сеанса клиента', 'pg_temp предназначена для временных таблиц.', NULL),
        ('option', 'В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', 'В первую существующую и доступную схему из явно указанных в пути поиска', 'В первую подходящую схему пути поиска', 'При этом нужно право CREATE в этой схеме.', 'В первую существующую и доступную схему из явно указанных в пути поиска: нужно право CREATE в этой схеме.'),
        ('option', 'Что происходит с временной схемой pg_temp_N по окончании сеанса?', 'Объекты удаляются, а сама схема остаётся для других сеансов', 'Объекты удаляются, схема остаётся другим', 'Схема потом достаётся другим сеансам.', 'Объекты удаляются, а сама схема остаётся и достаётся другим сеансам.'),
        ('option', 'Что происходит с временной схемой pg_temp_N по окончании сеанса?', 'Схема удаляется вместе с объектами', 'Схема удаляется вместе со всеми её объектами', 'Схема остаётся и используется другими сеансами.', NULL),
        ('option', 'Что происходит с временной схемой pg_temp_N по окончании сеанса?', 'Объекты переносятся в public', 'Объекты переносятся в схему public базы', 'Объекты никуда не переносятся.', NULL),
        ('option', 'Почему работа с временными таблицами быстрее, чем с обычными?', 'Хранятся только в кеше ОС', 'Хранятся в кеше ОС, а не на диске', 'Временные таблицы хранятся в файлах, а не только в кеше ОС.', 'Временные таблицы хранятся в файлах, а не в кеше ОС.'),
        ('option', 'Почему работа с временными таблицами быстрее, чем с обычными?', 'Для них не проверяются ограничения', 'Для них не проверяются ограничения таблицы', 'Ограничения проверяются как обычно.', NULL),
        ('option', 'Почему работа с временными таблицами быстрее, чем с обычными?', 'Они не журналируются и не попадают в общий буферный кеш', 'Не журналируются и не идут через общий буферный кеш', 'Данные временной таблицы не журналируются и обрабатываются в локальном буферном кеше сеанса.', 'Данные временной таблицы не журналируются и обрабатываются в локальном буферном кеше сеанса, а не в общем.'),
        ('option', 'Почему работа с временными таблицами быстрее, чем с обычными?', 'Их данные всегда сжимаются', 'Их данные сжимаются при каждой записи', 'Сжимаются только длинные значения через TOAST, как и в обычных таблицах.', 'Сжимаются длинные значения через TOAST, как и в обычных таблицах.'),
        ('option', 'Для чего нужны схемы?', 'Чтобы предотвратить конфликты имён между пользователями и приложениями', 'Чтобы избежать конфликтов имён между приложениями', 'Одинаковые имена могут жить в разных схемах.', NULL),
        ('option', 'Для чего нужны схемы?', 'Чтобы управлять физическим размещением данных на дисках', 'Чтобы управлять физическим размещением данных', 'Это задача табличных пространств.', NULL),
        ('option', 'Для чего нужны схемы?', 'Чтобы разделить объекты базы на логические группы', 'Чтобы делить объекты базы на логические группы', 'Так объектами удобнее управлять.', NULL),
        ('option', 'Что верно для схемы с именем пользователя в пути поиска по умолчанию?', 'Она входит в путь поиска, но сама не создаётся', 'Она входит в путь, но сама не создаётся', 'Если её создать и у пользователя есть права на неё, новые объекты без указания схемы будут попадать в неё.', NULL),
        ('option', 'Что изменилось для схемы public начиная с PostgreSQL 15?', 'Её больше нет в новых базах', 'Её больше нет в новых базах данных', 'Схема public по-прежнему есть.', NULL),
        ('option', 'Что изменилось для схемы public начиная с PostgreSQL 15?', 'Начальные права доступа к ней ограничены', 'Начальные права доступа к ней были ограничены', 'Раньше создавать в ней объекты мог любой пользователь.', NULL),
        ('option', 'Что изменилось для схемы public начиная с PostgreSQL 15?', 'Она стала частью системного каталога', 'Она стала частью системного каталога базы', 'Системный каталог находится в pg_catalog.', NULL),
        ('option', 'Как явно указать схему объекта в запросе?', 'Только через параметр search_path', 'Через параметр search_path', 'Путь поиска нужен для имён без схемы, а явное указание схемы работает всегда.', 'Путь поиска нужен для имён без схемы, а явное указание схемы работает независимо от него.'),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Именованный запрос, к результату которого можно обращаться как к таблице', 'Именованный запрос, результат которого читают как таблицу', 'Сохраняется определение запроса; обычное представление не хранит отдельную копию результата.', NULL),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Физическая копия таблицы, которая никогда не меняется', 'Физическая копия таблицы, которая не обновляется', 'Обычное представление получает данные из своего запроса.', NULL),
        ('option', 'Что такое обычное представление (VIEW) в PostgreSQL?', 'Обязательный индекс для каждой таблицы', 'Индекс, обязательный для каждой таблицы', 'Представление и индекс — разные объекты.', NULL),
        ('option', 'Есть автоматически обновляемое представление CREATE VIEW active_users AS SELECT id, active FROM users WHERE active; Выполняют DELETE FROM active_users WHERE id = 7; Видимая строка с id = 7 существует, права есть, мешающих ограничений и триггеров нет. Что удалится?', 'Только сохранённая копия строки внутри представления', 'Сохранённая копия строки внутри представления', 'У обычного представления нет отдельного хранилища этих строк.', NULL),
        ('option', 'Чем материализованное представление отличается от обычного представления?', 'Не имеет определяющего запроса', 'Не имеет определяющего запроса в каталоге базы', 'Запрос сохраняется и используется при обновлении результата.', NULL),
        ('option', 'Чем материализованное представление отличается от обычного представления?', 'Хранит результат запроса как данные, которые можно обновить отдельной командой', 'Хранит результат запроса, обновляемый командой', 'Сохранённый результат позволяет читать уже вычисленные строки.', 'Хранит результат запроса как данные, которые можно обновить отдельной командой REFRESH MATERIALIZED VIEW; сохранённый результат позволяет читать уже вычисленные строки.'),
        ('option', 'Чем материализованное представление отличается от обычного представления?', 'Всегда пересчитывает весь запрос при каждом SELECT', 'Пересчитывает весь запрос при каждом SELECT', 'SELECT обычно читает сохранённый результат.', 'SELECT обычно читает сохранённый результат, а не пересчитывает запрос.'),
        ('option', 'Чем материализованное представление отличается от обычного представления?', 'Может существовать только в памяти одного клиентского приложения', 'Может существовать в памяти клиентского приложения', 'Это объект базы данных на сервере.', NULL),
        ('option', 'Как заново вычислить и сохранить данные существующего материализованного представления monthly_sales?', '`REFRESH VIEW monthly_sales;`', '`REFRESH VIEW monthly_sales WITH DATA;`', 'Нужна форма REFRESH MATERIALIZED VIEW.', 'Такой команды нет: нужна форма REFRESH MATERIALIZED VIEW.'),
        ('option', 'Как заново вычислить и сохранить данные существующего материализованного представления monthly_sales?', '`ANALYZE monthly_sales;`', '`ANALYZE MATERIALIZED VIEW monthly_sales;`', 'ANALYZE собирает статистику для планировщика, а не пересчитывает результат запроса.', NULL),
        ('option', 'Как заново вычислить и сохранить данные существующего материализованного представления monthly_sales?', '`REINDEX TABLE monthly_sales;`', '`REINDEX TABLE monthly_sales CONCURRENTLY;`', 'REINDEX перестраивает индексы, а не данные определяющего запроса.', NULL),
        ('option', 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны?', 'После изменения исходных таблиц его данные могут оставаться устаревшими до обновления', 'Данные могут устареть после изменения исходных таблиц', 'Встроенный механизм не поддерживает результат автоматически при каждой записи в исходные таблицы.', NULL),
        ('option', 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны?', 'Любой INSERT в исходную таблицу автоматически вызывает REFRESH', 'Любой INSERT в исходную таблицу вызывает REFRESH', 'Такое поведение само по себе не появляется при создании материализованного представления.', NULL),
        ('option', 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны?', 'Сохранённый результат всегда совпадает с исходными таблицами без дополнительных действий', 'Сохранённый результат совпадает с исходными таблицами', 'Актуальность зависит от момента обновления.', NULL),
        ('option', 'Транзакция получила значение через nextval, а затем выполнила ROLLBACK. Будет ли это значение автоматически возвращено последовательности для повторной выдачи?', 'Да, но только после VACUUM', 'Да, но после выполнения VACUUM', 'VACUUM не возвращает последовательности значения отменённых транзакций.', NULL),
        ('option', 'Транзакция получила значение через nextval, а затем выполнила ROLLBACK. Будет ли это значение автоматически возвращено последовательности для повторной выдачи?', 'Да, любое изменение состояния последовательности откатывается вместе с таблицами', 'Да, состояние последовательности откатывается как таблицы', 'Для nextval действует другое правило: полученное значение не возвращается при откате.', NULL),
        ('option', 'Транзакция получила значение через nextval, а затем выполнила ROLLBACK. Будет ли это значение автоматически возвращено последовательности для повторной выдачи?', 'Нет, потому что ROLLBACK после nextval вообще запрещён', 'Нет, потому что ROLLBACK после nextval запрещён', 'Откат разрешён; он просто не отменяет выдачу значения.', NULL),
        ('option', 'Транзакция получила значение через nextval, а затем выполнила ROLLBACK. Будет ли это значение автоматически возвращено последовательности для повторной выдачи?', 'Нет, откат транзакции не отменяет уже выполненный nextval', 'Нет, откат не отменяет выполненный nextval', 'Из-за этого в нумерации могут появляться пропуски.', NULL),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'До первого nextval этой последовательности в текущем сеансе currval выдаст ошибку', 'До первого nextval в сеансе currval выдаст ошибку', 'В сеансе ещё нет последнего значения nextval для этой последовательности.', NULL),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'currval всегда показывает последнее значение, выданное любому сеансу', 'currval показывает последнее значение любого сеанса', 'Это не глобальное значение для всех подключений.', NULL),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'Чужой сеанс может вызвать nextval, не изменив результат нашего currval', 'Чужой nextval не изменяет наш currval', 'currval привязан к последнему nextval именно в текущем сеансе.', NULL),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'Каждый вызов currval продвигает последовательность на один шаг', 'Каждый currval продвигает последовательность на шаг', 'Для продвижения используют nextval.', NULL),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'currval вычисляет MAX(id) в использующей последовательность таблице', 'currval вычисляет MAX(id) таблицы последовательности', 'Он не сканирует таблицу и не вычисляет максимальный идентификатор.', NULL),
        ('option', 'Что такое ограничение целостности таблицы?', 'Лимит времени выполнения любого SELECT', 'Лимит времени выполнения любого запроса в сеансе', 'Время выполнения регулируется другими механизмами, например statement_timeout.', NULL),
        ('option', 'Что такое ограничение целостности таблицы?', 'Комментарий, который сервер никогда не проверяет', 'Комментарий к таблице, который сервер не проверяет', 'Ограничение имеет исполняемую проверку, а не только описание.', NULL),
        ('option', 'Что такое ограничение целостности таблицы?', 'Правило допустимости данных, которое PostgreSQL проверяет при соответствующих изменениях', 'Правило допустимости данных, проверяемое сервером', 'Ограничения защищают данные независимо от того, какое приложение отправило команду.', NULL),
        ('option', 'Что обеспечивает PRIMARY KEY для столбца или группы столбцов таблицы?', 'Автоматическую сортировку результатов всех запросов по ключу', 'Автоматическую сортировку результатов запросов по ключу', 'Порядок вывода задаётся ORDER BY.', NULL),
        ('option', 'Что обеспечивает PRIMARY KEY для столбца или группы столбцов таблицы?', 'Уникальность ключа и запрет NULL в каждом его столбце', 'Уникальность значений и запрет NULL в каждом столбце ключа', 'Первичный ключ позволяет однозначно идентифицировать строку.', NULL),
        ('option', 'Что обеспечивает PRIMARY KEY для столбца или группы столбцов таблицы?', 'Только автоматическую генерацию следующего номера', 'Автоматическую генерацию следующего номера ключа', 'Первичный ключ сам по себе не задаёт генератор значений.', NULL),
        ('option', 'Столбец orders.customer_id имеет немедленно проверяемый внешний ключ на customers.id. Что будет при вставке заказа с ненулевым customer_id, которого нет в customers?', 'Вставка будет отклонена из-за нарушения внешнего ключа', 'Вставка будет отклонена из-за нарушения ключа', 'Ссылка должна соответствовать существующему значению в связанной таблице.', NULL),
        ('option', 'Столбец orders.customer_id имеет немедленно проверяемый внешний ключ на customers.id. Что будет при вставке заказа с ненулевым customer_id, которого нет в customers?', 'Вставка пройдёт, потому что внешние ключи проверяются только при SELECT', 'Вставка пройдёт: внешние ключи проверяются при SELECT', 'Внешний ключ контролирует соответствующие изменения данных.', NULL),
        ('option', 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', 'Да: CHECK не нарушается, если его выражение даёт NULL', 'Да: CHECK не нарушается при выражении NULL', 'CHECK (price > 0) сам по себе допускает NULL; чтобы запретить NULL, рекомендуется добавить NOT NULL.', NULL),
        ('option', 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', 'Нет: любое CHECK автоматически запрещает NULL', 'Нет: любое ограничение CHECK запрещает NULL', 'CHECK и NOT NULL — разные проверки.', NULL),
        ('option', 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', 'Нет: при сравнении NULL > 0 всегда получается false', 'Нет: сравнение NULL > 0 даёт значение false', 'Результат такого сравнения — NULL, а не false.', NULL),
        ('option', 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', 'Да, но NULL автоматически заменится на 0', 'Да, но NULL автоматически заменится значением 0', 'CHECK проверяет значение, а не подставляет замену.', NULL),
        ('option', 'Столбец допускает NULL. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'UNIQUE NULLS NOT DISTINCT позволяет считать NULL равными при проверке уникальности', 'UNIQUE NULLS NOT DISTINCT считает NULL равными', 'Для одного столбца это запрещает повторный NULL.', NULL),
        ('option', 'Столбец допускает NULL. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'UNIQUE допускает сколько угодно одинаковых ненулевых значений', 'UNIQUE допускает любые повторяющиеся ненулевые значения', 'Повторяющиеся ненулевые ключи нарушают уникальность.', NULL),
        ('option', 'Столбец допускает NULL. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'Поведение NULL в UNIQUE можно изменить только настройкой всего сервера', 'Поведение NULL в UNIQUE меняется настройкой сервера', 'NULLS NOT DISTINCT указывается для конкретного ограничения или уникального индекса.', NULL),
        ('option', 'Столбец допускает NULL. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'Обычное UNIQUE по одному столбцу допускает несколько строк с NULL', 'Обычное UNIQUE допускает несколько строк с NULL', 'По умолчанию NULL не считаются равными при такой проверке уникальности.', NULL),
        ('option', 'Ограничение объявлено как UNIQUE DEFERRABLE, без INITIALLY DEFERRED, и в транзакции не выполнялась команда SET CONSTRAINTS. Когда проверяется уникальность?', 'В конце каждой команды; для следующих команд проверку можно заранее отложить до конца транзакции командой SET CONSTRAINTS ... DEFERRED', 'В конце каждой команды, пока не меняют режим', 'DEFERRABLE без уточнения означает INITIALLY IMMEDIATE: по умолчанию проверка идёт в конце команды.', 'DEFERRABLE без уточнения означает INITIALLY IMMEDIATE: по умолчанию проверка идёт в конце команды; для следующих команд её можно отложить до конца транзакции командой SET CONSTRAINTS ... DEFERRED.'),
        ('option', 'Ограничение объявлено как UNIQUE DEFERRABLE, без INITIALLY DEFERRED, и в транзакции не выполнялась команда SET CONSTRAINTS. Когда проверяется уникальность?', 'Никогда: DEFERRABLE отключает проверку уникальности', 'Не проверяется: DEFERRABLE отключает проверку', 'DEFERRABLE разрешает отложить проверку, но не отключает её; пока режим не изменён, действует INITIALLY IMMEDIATE.', NULL),
        ('option', 'Ограничение объявлено как UNIQUE DEFERRABLE, без INITIALLY DEFERRED, и в транзакции не выполнялась команда SET CONSTRAINTS. Когда проверяется уникальность?', 'Только в момент COMMIT', 'В момент COMMIT всей транзакции', 'Так будет при INITIALLY DEFERRED или после SET CONSTRAINTS ... DEFERRED, если затем не выполнить SET CONSTRAINTS ... IMMEDIATE.', NULL),
        ('option', 'Внешний ключ объявлен DEFERRABLE INITIALLY DEFERRED. Чем в этом случае ON DELETE RESTRICT отличается от ON DELETE NO ACTION?', 'Ничем: эти действия всегда работают одинаково', 'Различий нет: оба действия работают одинаково', 'Действия различаются: проверку NO ACTION можно отложить, а RESTRICT — нельзя.', NULL),
        ('option', 'Внешний ключ объявлен DEFERRABLE INITIALLY DEFERRED. Чем в этом случае ON DELETE RESTRICT отличается от ON DELETE NO ACTION?', 'RESTRICT удаляет и ссылающиеся строки, а NO ACTION — нет', 'RESTRICT удаляет ссылающиеся строки, NO ACTION нет', 'Удаление ссылающихся строк — это ON DELETE CASCADE.', NULL),
        ('option', 'Внешний ключ объявлен DEFERRABLE INITIALLY DEFERRED. Чем в этом случае ON DELETE RESTRICT отличается от ON DELETE NO ACTION?', 'Проверку NO ACTION можно отложить до конца транзакции, а проверку RESTRICT нельзя отложить за конец текущей команды, даже у отложенного ключа', 'NO ACTION можно отложить, RESTRICT нельзя', 'При INITIALLY DEFERRED проверка NO ACTION по умолчанию ждёт COMMIT; SET CONSTRAINTS ... IMMEDIATE может вызвать её раньше. RESTRICT не откладывается.', 'При INITIALLY DEFERRED проверка NO ACTION по умолчанию ждёт COMMIT; SET CONSTRAINTS ... IMMEDIATE может вызвать её раньше. RESTRICT не откладывается даже у отложенного ключа: он срабатывает сразу, в момент команды.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
